func retryOpen[T any](t *testing.T, ctx context.Context, open func(context.Context) (T, error)) T {
	t.Helper()
	for {
		attempt, cancel := context.WithTimeout(ctx, 10*time.Second)
		value, err := open(attempt)
		cancel()
		if err == nil {
			return value
		}
		if ctx.Err() != nil {
			t.Fatal(err)
		}
		time.Sleep(200 * time.Millisecond)
	}
}

e2e_start_log.text:
func (l *rolloutStartLog) add(unit, digest string) {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.starts = append(l.starts, [2]string{unit, digest})
}

// on lists the units in the order they first started on digest.
func (l *rolloutStartLog) on(digest string) []string {
	l.mu.Lock()
	defer l.mu.Unlock()
	var units []string
	for _, start := range l.starts {
		if start[1] == digest && !slices.Contains(units, start[0]) {
			units = append(units, start[0])
		}
	}
	return units
}

func (l *rolloutStartLog) all() [][2]string {
	l.mu.Lock()
	defer l.mu.Unlock()
	return slices.Clone(l.starts)
}

e2e_units.text:
func newRolloutTestUnit(t *testing.T, ctx context.Context, cell, root, id string, conn *nats.Conn,
	key ed25519.PrivateKey, binaries map[string]string, staged []string, starts *rolloutStartLog,
) *rolloutTestUnit {
	t.Helper()
	bad, err := os.ReadFile(binaries["bad"])
	if err != nil {
		t.Fatal(err)
	}
	sum := sha256.Sum256(bad)
	unit := &rolloutTestUnit{t: t, ctx: ctx, cell: cell, id: id, conn: conn, key: key, baked: binaries["from"],
		bad: hex.EncodeToString(sum[:]), starts: starts,
		layout:    selfupdate.Layout{Root: filepath.Join(root, "release-"+id), Owner: os.Getuid()},
		proofFile: filepath.Join(root, id+"-proof.json")}
	for _, name := range staged {
		stageRolloutTestRelease(t, unit.layout, binaries[name])
	}
	if _, err := selfupdate.Seed(unit.layout, unit.baked); err != nil {
		t.Fatal(err)
	}
	if err := unit.restart(ctx, rolloutTestSystemdUnit); err != nil {
		t.Fatal(err)
	}
	go unit.watchdog()
	return unit
}

// stageRolloutTestRelease installs path as a staged release without a
// current link, as a verified stage would.
func stageRolloutTestRelease(t *testing.T, layout selfupdate.Layout, path string) string {
	t.Helper()
	digest, err := selfupdate.Seed(layout, path)
	if err != nil {
		t.Fatal(err)
	}
	for _, name := range []string{filepath.Join(layout.ReleaseDir(digest), "baked"), filepath.Join(layout.Root, "current")} {
		if err := os.Remove(name); err != nil {
			t.Fatal(err)
		}
	}
	return digest
}

func (u *rolloutTestUnit) restart(_ context.Context, systemdUnit string) error {
	if systemdUnit != rolloutTestSystemdUnit {
		return fmt.Errorf("unexpected unit %s", systemdUnit)
	}
	u.mu.Lock()
	defer u.mu.Unlock()
	if u.stop != nil {
		u.stop()
	}
	unlock, err := u.layout.Lock()
	if err != nil {
		return err
	}
	_, prepareErr := selfupdate.Prepare(u.layout, systemdUnit, u.baked, selfupdate.ProofCheck{}, time.Now())
	current, currentErr := u.layout.Current()
	activation, pending, pendingErr := u.layout.Pending()
	unlock()
	if err := errors.Join(prepareErr, currentErr, pendingErr); err != nil {
		return err
	}
	u.runs = current
	u.starts.add(u.id, current)
	ctx, stop := context.WithCancel(u.ctx)
	u.stop = stop
	if current == u.bad {
		return nil
	}
	if pending && activation.Target == current {
		now := time.Now().UTC()
		wire, err := selfupdate.SignVersionProof(selfupdate.VersionProof{Schema: selfupdate.ProofSchema,
			ActivationID: activation.ActivationID, Unit: systemdUnit, BinarySHA256: current,
			ProcessID: int64(os.Getpid()), ObservedAt: now}, u.key, now)
		if err != nil {
			return err
		}
		if err := os.WriteFile(u.proofFile, wire, 0o644); err != nil {
			return err
		}
	}
	publisher := rolloutexec.Publisher{Conn: u.conn, Cell: u.cell, Unit: u.id, Key: u.key, Interval: rolloutTestInterval,
		Executable: u.layout.BinaryPath(current), Healthy: func() bool { return true }}
	go func() { _ = publisher.Run(ctx) }()
	return nil
}

// attachAgent makes the unit's watchdog the node's root step agent, as in
// the image: it applies the steps the unit's controller spools into spool
// and leaves the restart it owes to the watchdog.
func (u *rolloutTestUnit) attachAgent(leaders trust.Keyring, spool string, verifier selfupdate.Verifier) {
	u.mu.Lock()
	defer u.mu.Unlock()
	u.agent = &rolloutexec.Agent{Cell: u.cell, Unit: u.id, SystemdUnit: rolloutTestSystemdUnit, Layout: u.layout,
		Leaders: leaders, Restart: func(context.Context, string) error { return nil }}
	u.spool, u.verifier = spool, verifier
}

// watchdog is the selfupdate watchdog timer of the unit: it applies the
// spooled rollout step, then confirms or rolls back the activation and
// restarts the unit it owes a restart.
func (u *rolloutTestUnit) watchdog() {
	ticker := time.NewTicker(200 * time.Millisecond)
	defer ticker.Stop()
	for {
		select {
		case <-u.ctx.Done():
			return
		case <-ticker.C:
		}
		u.mu.Lock()
		agent, spool, verifier := u.agent, u.spool, u.verifier
		u.mu.Unlock()
		if agent != nil {
			if err := rolloutexec.ApplySpooled(u.ctx, agent, spool, verifier); err != nil {
				u.t.Logf("unit %s step agent: %v", u.id, err)
			}
		}
		unlock, err := u.layout.Lock()
		if err != nil {
			continue
		}
		_, _, watchErr := selfupdate.Watch(u.layout, rolloutTestSystemdUnit,
			selfupdate.ProofCheck{File: u.proofFile, PublicKey: u.key.Public().(ed25519.PublicKey)}, time.Now())
		owed, owedErr := u.layout.RestartPending(rolloutTestSystemdUnit)
		unlock()
		if watchErr == nil && owedErr == nil && owed {
			_ = u.restart(u.ctx, rolloutTestSystemdUnit)
		}
	}
}

// settledOn reports a unit running digest with no pending activation.
func (u *rolloutTestUnit) settledOn(digest string) bool {
	u.mu.Lock()
	runs := u.runs
	u.mu.Unlock()
	unlock, err := u.layout.Lock()
	if err != nil {
		return false
	}
	defer unlock()
	_, pending, err := u.layout.Pending()
	return err == nil && !pending && runs == digest
}

exec_run.text:
func (e *Executor) Run(ctx context.Context) error {
	if e.Store == nil || e.Fencer == nil || e.Driver == nil || e.Proofs == nil {
		return fmt.Errorf("%w: rollout executor needs a store, fencer, driver and proof source", ErrInvalid)
	}
	interval := e.Interval
	if interval <= 0 {
		interval = DefaultInterval
	}
	ticker := time.NewTicker(interval)
	defer ticker.Stop()
	for {
		ctx := observability.StartTrace(ctx)
		if err := e.Tick(ctx); err != nil && ctx.Err() == nil {
			slog.WarnContext(ctx, "rollout executor tick failed", "component", "rollout", "error", err)
		}
		select {
		case <-ctx.Done():
			return ctx.Err()
		case <-ticker.C:
		case <-e.Wake:
		}
	}
}

// Tick runs one leader-only pass: adopt the active rollout under the
// current epoch, derive its next actions, perform them, and commit the
// events they produced. A follower forgets its leader-local memory.
func (e *Executor) Tick(ctx context.Context) error {
	snapshot := e.Fencer.Current()
	if !snapshot.CanMutate() {
		e.forget("")
		return nil
	}
	if e.issued == nil {
		e.forget("")
	}
	if err := e.Store.RecoverReservation(ctx, snapshot.Epoch); err != nil {
		return err
	}
	record, revision, ok, err := e.Store.Active(ctx)
	if err != nil {
		return err
	}
	if !ok {
		e.forget("")
		if err := e.startNext(ctx, snapshot.Epoch); err != nil {
			e.waiting = err.Error()
			e.publish(snapshot.Epoch, nil)
			return err
		}
		if record, revision, ok, err = e.Store.Active(ctx); err != nil || !ok {
			e.publish(snapshot.Epoch, nil)
			return err
		}
	}
	if record.RolloutID != e.rolloutID {
		e.forget(record.RolloutID)

apply_spooled.text:
func ApplySpooled(ctx context.Context, agent *Agent, dir string, verifier selfupdate.Verifier) error {
	spool, err := os.OpenRoot(dir)
	if errors.Is(err, fs.ErrNotExist) {
		return nil
	}
	if err != nil {
		return err
	}
	defer spool.Close()
	wire, err := readSpooled(spool, spoolStep, trust.MaxEnvelopeBytes)
	if errors.Is(err, fs.ErrNotExist) {
		return nil
	}
	if err != nil {
		return err
	}
	command, expires, err := VerifyStepCommand(wire, agent.Cell, agent.Unit, agent.Leaders, agent.now())
	if err != nil {
		return nil
	}
	if verifier != nil {
		agent.Fetch = spoolFetcher{spool: spool, verifier: verifier, now: agent.now}
	}
	data, err := json.Marshal(agent.handle(ctx, command, expires))
	if err != nil {
		return err
	}
	return writeFileAtomic(filepath.Join(agent.Layout.Root, ReplyFile(agent.SystemdUnit)), data, 0o644)
}

agent_apply.text:
func (a *Agent) handle(ctx context.Context, command StepCommand, expires time.Time) StepReply {
	reply := StepReply{OperationID: command.OperationID, Unit: a.Unit, Epoch: command.Epoch}
	a.mu.Lock()
	defer a.mu.Unlock()
	window := max(selfupdate.MinProofWindow, min(selfupdate.MaxProofWindow,
		time.Duration(command.ProofWindowSeconds)*time.Second))
	// Nothing, staging included, outlives the signed command.
	stepCtx, cancel := context.WithDeadline(ctx, expires)
	defer cancel()
	reply.Outcome, reply.Reason = a.apply(stepCtx, command, expires, window)
	return reply
}

// apply fences the step by its authority epoch, which the release root
// records durably: an older leader's step is refused even after this agent
// restarted. The restart obligation is recorded before the release changes
// and cleared only by the unit's next start, so any interruption leaves the
// watchdog (and a retry by a new agent) a restart to finish.
func (a *Agent) apply(ctx context.Context, command StepCommand, expires time.Time, window time.Duration) (StepOutcome, string) {
	if outcome, reason := a.locked(func() (StepOutcome, string) {
		if a.Guard != nil {
			if err := a.Guard(ctx, command); err != nil {
				return OutcomeRefused, err.Error()
			}
		}
		return a.admit(command)
	}); outcome != "" {
		return outcome, reason
	}
	if outcome, reason := a.ensureStaged(ctx, command); outcome != "" {
		return outcome, reason
	}
	outcome, reason := a.locked(func() (StepOutcome, string) {
		// Re-checked under the lock, immediately before the selection
		// changes: waiting for the lock or a staging download must not
		// let an expired command act.
		if !a.now().Before(expires) {
			return OutcomeRetry, "step command expired before it could be applied"
		}
		if a.Guard != nil {
			if err := a.Guard(ctx, command); err != nil {
				return OutcomeRefused, err.Error()
			}
		}
		if outcome, reason := a.admit(command); outcome != "" {
			return outcome, reason
		}
		if command.Action == StepRollback {
			return a.restore(command)
		}
		return a.activate(command, window)
	})
	if !outcome.Accepted() {
		return outcome, reason
	}
	owed, err := a.owed()
	if err != nil {
		return OutcomeRetry, "restart obligation is unreadable"
	}
	if !owed || a.served == command.OperationID && outcome != OutcomeActivated {
		return outcome, reason
	}
	if err := a.restart(ctx); err != nil {
		slog.WarnContext(ctx, "rollout agent could not restart its unit", "component", "rollout", "unit", a.Unit, "error", err)
		return OutcomeRetry, "unit restart failed"
	}
	a.served = command.OperationID
	return outcome, reason
}

// admit records the step's epoch, refusing an older one. The caller holds
// Layout.Lock.
func (a *Agent) admit(command StepCommand) (StepOutcome, string) {
	if err := a.Layout.AdmitEpoch(command.Epoch); errors.Is(err, selfupdate.ErrStaleEpoch) {
		return OutcomeRefused, "step is from an older authority epoch"
	} else if err != nil {
		return OutcomeRetry, "authority epoch record is unreadable"
	}
	return "", ""
}

func (a *Agent) owed() (bool, error) {
	unlock, err := a.Layout.Lock()
	if err != nil {
		return false, err
	}
	defer unlock()
	return a.Layout.RestartPending(a.SystemdUnit)
}

// locked runs step under Layout.Lock.
func (a *Agent) locked(step func() (StepOutcome, string)) (StepOutcome, string) {
	unlock, err := a.Layout.Lock()
	if err != nil {
		return OutcomeRetry, "release root is locked"
	}
	defer unlock()
	return step()
}

// ensureStaged restages a release that is not in the release root (a
// rollback target pruned after its activation settled) from the step's
// signed receipt. It runs unlocked, like selfupdate's own fetch.
func (a *Agent) ensureStaged(ctx context.Context, command StepCommand) (StepOutcome, string) {
	err := a.Layout.VerifyRelease(command.Digest)
	switch {
	case err == nil:
		return "", ""
	case !errors.Is(err, fs.ErrNotExist):
		return OutcomeRefused, "staged release does not verify"
	case a.Fetch == nil || len(command.Receipt) == 0:
		return OutcomeRefused, "release is not staged and cannot be restaged"
	}
	staged, err := a.Fetch.Fetch(ctx, a.Layout, command.Receipt, command.Delegation)
	if err != nil {
		slog.WarnContext(ctx, "rollout agent could not stage a release", "component", "rollout", "unit", a.Unit,

seed_release.text:
func Seed(layout Layout, bakedBinary string) (string, error) {
	if err := layout.ensureDirs(); err != nil {
		return "", err
	}
	current, err := layout.Current()
	if err != nil || current != "" {
		return current, err
	}
	file, err := os.Open(bakedBinary)
	if err != nil {
		return "", err
	}
	defer file.Close()
	info, err := file.Stat()
	if err != nil || !info.Mode().IsRegular() || info.Size() <= 0 || info.Size() > MaxBinaryBytes {
		return "", fmt.Errorf("%w: baked binary", ErrInvalid)
	}
	digest, _, err := hashFile(bakedBinary)
	if err != nil {
		return "", err
	}
	if _, err := os.Lstat(layout.ReleaseDir(digest)); errors.Is(err, os.ErrNotExist) {
		if err := layout.install(file, digest, info.Size(), map[string][]byte{bakedMarkerFile: []byte(bakedBinary + "\n")}); err != nil {
			return "", err
		}
	}
	if err := layout.VerifyRelease(digest); err != nil {
		return "", err
	}
	return digest, layout.flipCurrent(digest)
}

self_watch.text:
func Watch(layout Layout, unit string, proof ProofCheck, now time.Time) (Outcome, Activation, error) {
	// A rollout restore interrupted before its link moved is finished
	// first, so neither the watchdog's restart nor the unit's start ever
	// runs the release the restore rejected.
	if err := layout.finishRestores(); err != nil {
		return OutcomeIdle, Activation{}, fmt.Errorf("finish interrupted restore: %w", err)
	}
	activation, pending, err := layout.Pending()
	if errors.Is(err, ErrUnreadableActivation) {
		return layout.resolveUnreadable(err)
	}
	if err != nil || !pending {
		return OutcomeIdle, Activation{}, err
	}
	if activation.Unit != unit {
		// Another unit's watchdog resolves this activation. Once it is long
		// past its deadline no functioning watchdog is left to do so (a
		// mistyped unit, or a unit without the drop-ins): roll it back so it
		// cannot block every later activation on this node.
		if now.Before(activation.Deadline.Add(OrphanedActivationGrace)) {
			return OutcomePending, activation, nil
		}
		slog.Warn("self-update activation of an unwatched unit expired; rolling back",
			"activation", activation.ActivationID, "unit", activation.Unit)
		if err := layout.rollback(activation); err != nil {
			return OutcomeRolledBack, activation, err
		}
		recordResolution(activation, OutcomeRolledBack)
		return OutcomeRolledBack, activation, nil
	}
	// rollback marks the target known bad before it moves the link and
	// removes the record. A known-bad target therefore means a rollback was
	// committed and interrupted: finish it instead of accepting a proof.
	knownBad, err := layout.KnownBad()
	if err != nil {
		return OutcomePending, activation, err
	}
	if knownBad[activation.Target] {
		slog.Warn("self-update rollback was interrupted; finishing it", "activation", activation.ActivationID)
		if err := layout.rollback(activation); err != nil {
			return OutcomeRolledBack, activation, err
		}
		recordResolution(activation, OutcomeRolledBack)
		return OutcomeRolledBack, activation, nil
	}
	// Only a target that is actually selected can be confirmed. Otherwise
	// the activation stays pending until its deadline rolls it back.
	current, err := layout.Current()
	if err != nil {
		return OutcomePending, activation, err
	}
	targetErr := layout.VerifyRelease(activation.Target)
	if targetErr == nil && current == activation.Target && len(proof.PublicKey) == ed25519.PublicKeySize {
		if wire, err := readProof(proof.File); err == nil {
			if verified, err := VerifyVersionProof(wire, proof.PublicKey, activation, now); err == nil && !processRunning(verified.ProcessID) {
				// A proof only confirms while the process that signed it
				// still runs: one that crashed right after proving must not
				// confirm the activation at the next check.
				slog.Warn("self-update version proof process is gone", "activation", activation.ActivationID, "pid", verified.ProcessID)
			} else if err == nil {
				if err := layout.rememberConfirmed(activation.Target); err != nil {
					return OutcomePending, activation, err
				}
				// The confirmed release runs the image's root steps from
				// now on (Delegate).
				if err := layout.flipLink(knownGoodLink, activation.Target); err != nil {
					return OutcomePending, activation, err
				}
				if err := os.Remove(layout.activationPath()); err != nil {
					return OutcomePending, activation, err
				}
				if err := syncDir(layout.Root); err != nil {
					return OutcomeConfirmed, activation, err
				}

self_prepare.text:
func Prepare(layout Layout, unit, bakedBinary string, proof ProofCheck, now time.Time) (Outcome, error) {
	if _, err := Seed(layout, bakedBinary); err != nil {
		return OutcomeIdle, fmt.Errorf("seed baked release: %w", err)
	}
	// Prepare runs while the unit (re)starts, so the process behind any
	// existing proof is gone: a proof never confirms across a restart. The
	// new process proves itself again for the watchdog; prepare only
	// resolves expired, unwatched or unreadable activations; its proof
	// argument is accepted for the drop-in's flags and not used to confirm.
	outcome, activation, err := Watch(layout, unit, ProofCheck{}, now)
	if err != nil {
		return outcome, err
	}
	// The unit is starting now, so any restart a rollback still owed it is
	// being served by this start.
	if unitRE.MatchString(unit) {
		if err := layout.ClearRestartPending(unit); err != nil {
			return outcome, err
		}
	}
	current, err := layout.Current()
	if err != nil {
		return outcome, err
	}
	// The units on a node share the current link. A unit never starts the
	// unconfirmed target of another unit's activation: it cannot prove it,
	// and that activation's rollback does not restart it. Its restart policy
	// retries once the activation is resolved.
	if outcome == OutcomePending && activation.Unit != unit && current == activation.Target {
		return outcome, fmt.Errorf("%w: %s waits for the pending activation of %s", ErrInvalid, unit, activation.Unit)
	}
	if err := layout.VerifyRelease(current); err != nil {
		return outcome, fmt.Errorf("current release does not verify: %w", err)
	}
	if removed, err := layout.PruneReleases(now); err != nil {
		slog.Warn("self-update release pruning failed", "error", err)
	} else if len(removed) > 0 {
		slog.Info("self-update pruned settled releases", "releases", removed)
	}
	return outcome, nil
}

