func newHostSinkFixture(t *testing.T) *hostSinkFixture {
	t.Helper()
	js := testRolloutJetStream(t)
	store, err := rollout.OpenStore(t.Context(), js, "gru", 1, rolloutTestFence{epoch: 7})
	if err != nil {
		t.Fatal(err)
	}
	board, err := js.KeyValue(t.Context(), rollout.Bucket)
	if err != nil {
		t.Fatal(err)
	}
	public, key, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	control := &rolloutControl{cell: "gru", layout: selfupdate.Layout{Root: t.TempDir(), Owner: os.Getuid()}}
	control.hosts.Store(&rolloutHosts{collector: rolloutexec.NewCollector("gru", nil, nil), board: board,
		colocated: colocatedNodes("gru", []rollout.Unit{{ID: "controller-a", Group: "controllers"}}, renamedSlotA),
		last:      map[string]time.Time{}, held: map[string]time.Time{}})
	return &hostSinkFixture{control: control, board: board, js: js, store: store, key: key, host: host.Registration{Cell: "gru",
		Node: "gru-1-db-1", Roles: []string{"terrabase"}, PublicKey: base64.StdEncoding.EncodeToString(public)}}
}

// renamedSlotA is a cell spec whose host grant names controller-a's VM
// ts-gru-1 (TS-609).
func renamedSlotA(slot string) string {
	if slot == "controller-a" {
		return "ts-gru-1"
	}
	return "gru-" + slot
}

func (f *hostSinkFixture) proof(t *testing.T, key ed25519.PrivateKey) []byte {
	t.Helper()
	now := time.Now().UTC()
	wire, err := rolloutexec.SignHealthProof(rolloutexec.HealthProof{Schema: rolloutexec.HealthSchema, Cell: "gru",
		Unit: f.host.Node, BinarySHA256: strings.Repeat("a", 64), ProcessID: 7, StartNonce: "00000000000000000000000000000001",
		ObservedAt: now}, key, now)
	if err != nil {
		t.Fatal(err)
	}
	return wire
}

// exchange runs one exchange as if a proof interval had passed since the
// host's previous one.
func (f *hostSinkFixture) exchange(t *testing.T, exchange host.RolloutExchange) (host.RolloutStep, error) {
	t.Helper()
	hosts := f.control.hosts.Load()
	hosts.mu.Lock()
	delete(hosts.last, f.host.Node)
	hosts.mu.Unlock()
	return f.control.Exchange(t.Context(), f.host, exchange)
}

func (f *hostSinkFixture) joined(t *testing.T, node string) bool {
	t.Helper()
	_, err := f.board.Get(t.Context(), rollout.HostMembershipKey(node))
	return err == nil
}

host_exchange.text:
func (c *rolloutControl) Exchange(ctx context.Context, registration host.Registration, exchange host.RolloutExchange,
) (host.RolloutStep, error) {
	hosts := c.hosts.Load()
	if hosts == nil {
		return host.RolloutStep{}, errors.New("the rollout executor is not running")
	}
	node := registration.Node
	if hosts.colocated(node) {
		return host.RolloutStep{}, errors.New("a host on a controller's VM moves with its controller")
	}
	if len(exchange.Reply) > maxHostReply {
		return host.RolloutStep{}, errors.New("host rollout reply is too large")
	}
	now := time.Now()
	hosts.mu.Lock()
	if last, seen := hosts.last[node]; seen && now.Sub(last) < rolloutexec.DefaultProofInterval/2 {
		hosts.mu.Unlock()
		return host.RolloutStep{}, errors.New("host rollout exchange is too frequent")
	}
	hosts.last[node] = now
	hosts.mu.Unlock()
	public, err := decodePublicKey(registration.PublicKey)
	if err != nil {
		return host.RolloutStep{}, err
	}
	keys, err := trust.ParseKeyring(public)
	if err != nil {
		return host.RolloutStep{}, err
	}
	if err := hosts.collector.ObserveFrom(node, exchange.Proof, keys); err != nil {
		return host.RolloutStep{}, fmt.Errorf("host health proof: %w", err)
	}
	hosts.mu.Lock()
	if exchange.Held {
		hosts.held[node] = now
	} else {
		delete(hosts.held, node)
	}
	hosts.mu.Unlock()
	membership, err := protocol.EncodeJSON(rollout.HostMembership{Node: node, PublicKey: registration.PublicKey})
	if err != nil {
		return host.RolloutStep{}, err
	}
	if err := putChanged(ctx, hosts.board, rollout.HostMembershipKey(node), membership); err != nil {
		return host.RolloutStep{}, err
	}
	// Root independently verifies the original signature and current membership.
	if c.conn != nil {
		if err := c.conn.Publish(protocol.RolloutProofSubject(c.cell, node), exchange.Proof); err != nil {
			return host.RolloutStep{}, err
		}
	}
	if len(exchange.Reply) > 0 {
		var reply rolloutexec.StepReply
		if err := json.Unmarshal(exchange.Reply, &reply); err != nil || reply.Unit != node {
			return host.RolloutStep{}, errors.New("host rollout reply is invalid")
		}
		if err := putChanged(ctx, hosts.board, rolloutexec.ReplyKey(node), exchange.Reply); err != nil {
			return host.RolloutStep{}, err
		}
	}
	entry, err := hosts.board.Get(ctx, rolloutexec.StepKey(node))
	if errors.Is(err, jetstream.ErrKeyNotFound) {
		return host.RolloutStep{}, nil
	}
	if err != nil {
		return host.RolloutStep{}, err
	}
	return host.RolloutStep{Step: entry.Value()}, nil
}

host_held.text:
func (h *rolloutHosts) heldBy(node string) bool {
	h.mu.Lock()
	defer h.mu.Unlock()
	at, held := h.held[node]
	return held && time.Since(at) < 3*rolloutexec.DefaultProofInterval
}

host_put.text:
func putChanged(ctx context.Context, kv jetstream.KeyValue, key string, value []byte) error {
	entry, err := kv.Get(ctx, key)
	if err == nil && bytes.Equal(entry.Value(), value) {
		return nil
	}
	if err != nil && !errors.Is(err, jetstream.ErrKeyNotFound) {
		return err
	}
	_, err = kv.Put(ctx, key, value)
	return err
}

host_binary.text:
func (c *rolloutControl) Binary(_ context.Context, digest string, offset int64, limit int) (host.RolloutChunk, error) {
	file, err := os.Open(c.layout.BinaryPath(digest))
	if err != nil {
		return host.RolloutChunk{}, fmt.Errorf("release %s is not on this controller", digest)
	}
	defer file.Close()
	info, err := file.Stat()
	if err != nil || !info.Mode().IsRegular() || offset > info.Size() {
		return host.RolloutChunk{}, errors.New("rollout binary query is outside the release")
	}
	data := make([]byte, min(int64(limit), info.Size()-offset))
	if _, err := file.ReadAt(data, offset); err != nil && !errors.Is(err, io.EOF) {
		return host.RolloutChunk{}, err
	}
	return host.RolloutChunk{Data: data, Size: info.Size()}, nil
}

host_colocated.text:
func colocatedNodes(cell string, controllers []rollout.Unit, nodeOf func(string) string) func(string) bool {
	return func(node string) bool {
		for _, controller := range controllers {
			if node == controller.ID || node == nodeOf(controller.ID) {
				return true
			}
			if name, err := naming.RegionCell(strings.ToUpper(cell)).ControllerSlot(controller.ID); err == nil && name == node {
				return true
			}
		}
		return false
	}
}

root_proofs.text:
func (p rootChannelProofs) Latest(unit string) (rolloutexec.HealthProof, bool) {
	latest, ok := p.b.proofs.Latest(unit)
	if !ok || p.ctx.Err() != nil {
		return rolloutexec.HealthProof{}, false
	}
	p.b.mu.Lock()
	wire := bytes.Clone(p.b.proofWires[unit])
	p.b.mu.Unlock()
	keys, err := p.b.keys(unit)
	if err != nil {
		return rolloutexec.HealthProof{}, false
	}
	verified, err := rolloutexec.VerifyHealthProof(wire, p.b.cfg.NATS.Cell, unit, keys, time.Now().UTC())
	if err != nil || latest.ProcessID != verified.ProcessID || latest.StartNonce != verified.StartNonce || !latest.ObservedAt.Equal(verified.ObservedAt) || latest.BinarySHA256 != verified.BinarySHA256 {
		return rolloutexec.HealthProof{}, false
	}
	if p.ctx.Err() != nil {
		return rolloutexec.HealthProof{}, false
	}
	if p.observation != nil {
		if err := p.observation.pinProof(p.ctx, unit, latest, wire); err != nil {
			return rolloutexec.HealthProof{}, false
		}
	}
	return latest, true
}

collector.text:
func NewCollector(cell string, keys KeyResolver, now func() time.Time) *Collector {
	if now == nil {
		now = time.Now
	}
	return &Collector{cell: cell, keys: keys, now: now, latest: map[string]HealthProof{},
		retired: map[string][]retiredIncarnation{}}
}

// Observe verifies one proof received on subject and records it. A proof
// that arrived on another unit's subject, is older than the unit's newest
// proof, or fails verification is dropped with an error.
func (c *Collector) Observe(subject string, wire []byte) error {
	envelope, err := trust.DecodeEnvelope(wire)
	if err != nil {
		return err
	}
	var payload HealthProof
	if err := protocol.DecodeStrict(envelope.Payload, &payload, trust.MaxPayloadBytes); err != nil {
		return err
	}
	unit := payload.Unit
	if !unitRE.MatchString(unit) || subject != protocol.RolloutProofSubject(c.cell, unit) {
		return fmt.Errorf("%w: health proof subject", ErrInvalid)
	}
	if c.keys == nil {
		return fmt.Errorf("%w: no proof keys", ErrInvalid)
	}
	keys, err := c.keys(unit)
	if err != nil {
		return err
	}
	return c.accept(unit, wire, keys)
}

// ObserveFrom records a proof that reached the leader over another
// authenticated path than the proof subject, a host's session, verified
// with keys, the unit's own.
func (c *Collector) ObserveFrom(unit string, wire []byte, keys trust.Keyring) error {
	if !unitRE.MatchString(unit) || len(keys) == 0 {
		return fmt.Errorf("%w: health proof unit", ErrInvalid)
	}
	return c.accept(unit, wire, keys)
}

func (c *Collector) accept(unit string, wire []byte, keys trust.Keyring) error {
	proof, err := VerifyHealthProof(wire, c.cell, unit, keys, c.now())
	if err != nil {
		return err
	}
	now := c.now().UTC()
	proof.ReceivedAt = now
	c.mu.Lock()
	defer c.mu.Unlock()
	// A superseded process never becomes current again: a delayed or
	// replayed proof of it is refused while any proof it signed verifies.
	retired := slices.DeleteFunc(c.retired[unit], func(r retiredIncarnation) bool { return !now.Before(r.until) })
	c.retired[unit] = retired
	if slices.ContainsFunc(retired, func(r retiredIncarnation) bool {
		return r.processID == proof.ProcessID && r.startNonce == proof.StartNonce
	}) {
		return nil
	}
	previous, exists := c.latest[unit]
	// Within one incarnation proofs only move forward. Another
	// incarnation whose clock reads earlier (a clock stepped back across a
	// restart) replaces the newest one only after that one went quiet.
	if exists && !proof.ObservedAt.After(previous.ObservedAt) &&
		(proof.sameIncarnation(previous) || proof.ReceivedAt.Sub(previous.ReceivedAt) <= incarnationQuiet) {
		return nil
	}
	if !exists && len(c.latest) >= maxProofUnits {
		// An expired proof completes nothing: reclaim the units that
		// stopped proving (removed or replaced) before refusing a new one.
		for id, held := range c.latest {
			if now.Sub(held.ReceivedAt) > retiredFor {
				delete(c.latest, id)
				delete(c.retired, id)
			}
		}
		if len(c.latest) >= maxProofUnits {
			return fmt.Errorf("%w: too many proof units", ErrInvalid)
		}
	}
	if exists && !proof.sameIncarnation(previous) {
		if len(retired) >= maxRetired {
			retired = slices.Delete(retired, 0, len(retired)-maxRetired+1)
		}
		c.retired[unit] = append(retired, retiredIncarnation{processID: previous.ProcessID,
			startNonce: previous.StartNonce, until: now.Add(retiredFor)})
	}
	c.latest[unit] = proof
	if c.Arrived != nil {
		select {
		case c.Arrived <- struct{}{}:
		default:
		}
	}
	return nil
}

// Latest returns unit's newest verified proof.
func (c *Collector) Latest(unit string) (HealthProof, bool) {
	c.mu.Lock()
	defer c.mu.Unlock()
	proof, exists := c.latest[unit]
	return proof, exists
}

// Subscribe feeds every unit's proofs in the cell into the collector.
func (c *Collector) Subscribe(conn *nats.Conn) (*nats.Subscription, error) {
	if conn == nil {
		return nil, fmt.Errorf("%w: proof collector needs a connection", ErrInvalid)
	}
	return conn.Subscribe(protocol.RolloutProofSubject(c.cell, ""), func(msg *nats.Msg) {
		if err := c.Observe(msg.Subject, msg.Data); err != nil {
			slog.Debug("rollout health proof dropped", "component", "rollout", "error", err)
		}
	})
}

